// Generated by Cypress Author on 2026-10-19
//
// SUI 04 · SUI 05 (P0) — Plano_de_Testes_QA_MatchWallet.md §9.1.
// A classificação é do servidor. Recalculamos pontuação e perfil de forma independente da UI
// (soma dos pesos + faixas vigentes) e comparamos; e provamos que o cliente não grava avaliação
// em nome de outro usuário. Usa contas DESCARTÁVEIS: não altera os clientes fixos.
//
// ATENÇÃO: o front envia `usuarioId` no corpo porque a rota `/suitability/avaliar` não lê o
// JWT (INTEGRATION_PROMPT.md §4.2). Se o servidor aceitar o `usuarioId` de outra pessoa, o segundo
// teste FALHA — e isso é um defeito de segurança real, não do teste.

interface Pergunta {
  id: string
  opcoes: Array<{ id: string; peso: number }>
}

interface Faixa {
  perfil: string
  min: number
  max: number
}

describe('Plano QA · Suitability no servidor', () => {
  it('SUI 04 · avalia com respostas conhecidas → pontuação = soma dos pesos e perfil = faixa vigente', () => {
    cy.loginReal('admin')
    cy.apiRequest<{ faixas: Faixa[] }>({ method: 'GET', url: '/configuracoes/suitability' })
      .its('body.faixas')
      .as('faixas')
    cy.clearCookies()

    cy.apiRequest<Pergunta[]>({ method: 'GET', url: '/suitability/perguntas' }).then(
      ({ body: perguntas }) => {
        // Sempre a última opção de cada pergunta: caminho determinístico.
        const escolhas = perguntas.map((p) => ({
          perguntaId: p.id,
          opcao: p.opcoes[p.opcoes.length - 1],
        }))
        const somaEsperada = escolhas.reduce((total, e) => total + e.opcao.peso, 0)

        cy.criarUsuarioDescartavel().then((conta) => {
          cy.loginComo(conta)
          cy.apiRequest<{ usuarioId: string; pontuacaoTotal: number; perfilResultante: string }>({
            method: 'POST',
            url: '/suitability/avaliar',
            body: {
              usuarioId: conta.id,
              respostas: escolhas.map((e) => ({ perguntaId: e.perguntaId, opcaoId: e.opcao.id })),
            },
          }).then(({ body }) => {
            expect(body.usuarioId).to.eq(conta.id)
            expect(body.pontuacaoTotal, 'pontuação total').to.eq(somaEsperada)

            cy.get<Faixa[]>('@faixas').then((faixas) => {
              const esperado = faixas.find((f) => somaEsperada >= f.min && somaEsperada <= f.max)
              expect(esperado, `faixa para ${somaEsperada} pontos`).to.exist
              expect(body.perfilResultante).to.eq(esperado?.perfil)
            })
          })
        })
      },
    )
  })

  it('SUI 04 · cliente envia o usuarioId de outra pessoa → servidor não grava avaliação para a vítima', () => {
    cy.apiRequest<Pergunta[]>({ method: 'GET', url: '/suitability/perguntas' }).then(
      ({ body: perguntas }) => {
        const respostas = perguntas.map((p) => ({ perguntaId: p.id, opcaoId: p.opcoes[0].id }))

        cy.criarUsuarioDescartavel().then((vitima) => {
          cy.criarUsuarioDescartavel().then((atacante) => {
            cy.loginComo(atacante)
            cy.apiRequest({
              method: 'POST',
              url: '/suitability/avaliar',
              body: { usuarioId: vitima.id, respostas },
              failOnStatusCode: false,
            }).then(({ status, body }) => {
              // Ou recusa, ou grava para o dono da sessão — jamais para a vítima.
              if (status >= 200 && status < 300) {
                expect((body as { usuarioId: string }).usuarioId).to.eq(atacante.id)
              }
            })

            // Histórico da vítima, lido por um admin, continua vazio.
            cy.clearCookies()
            cy.loginReal('admin')
            cy.apiRequest<unknown[]>({
              method: 'GET',
              url: `/usuarios/${vitima.id}/historico-suitability`,
            })
              .its('body')
              .should('have.length', 0)
          })
        })
      },
    )
  })
})

export {}
